1	import { DESIGN_COLLECTIONS } from '@modules/door-model/const';
2	import {
3	  useDoorCollection,
4	  useDoorDesign,
5	  useSetDoorDesign,
6	} from '@modules/door-model/store';
7	import { isCollectionGuard } from '@modules/door-model/util';
8	import { FC, useMemo } from 'react';
9	import { OptionListItem } from '../OptionListItem';
10	import { OptionListTitle } from '../OptionListTitle';
11	
12	export const Design: FC = () => {
13	  const collection = useDoorCollection();
14	  const design = useDoorDesign();
15	  const currentDesigns = useMemo(() => {
16	    if (!collection.name || !isCollectionGuard(collection.name)) {
17	      return DESIGN_COLLECTIONS['Horizont'];
18	    }
19	    return DESIGN_COLLECTIONS[collection.name];
20	  }, [collection.name]);
21	
22	  const setDesign = useSetDoorDesign();
23	
24	  return (
25	    <>
26	      <OptionListTitle title="Design" value={design.name} />
27	      <div className="flex mb-40 flex-wrap">
28	        {currentDesigns.map((item) => (
29	          <OptionListItem
30	            key={item.id}
31	            item={item}
32	            activeItem={design}
33	            imageWidth={32}
34	            imageHeight={56}
35	            setDirection={setDesign}
36	          />
37	        ))}
38	      </div>
39	    </>
40	  );
41	};
