1	import clsx from 'clsx';
2	import Image from 'next/image';
3	import { FC, useMemo } from 'react';
4	
5	interface Props {
6	  item: DoorItem;
7	  activeItem: DoorItem;
8	  hasOpacity?: boolean;
9	  imageWidth?: number;
10	  imageHeight?: number;
11	  setDirection: (item: DoorItem) => void;
12	}
13	
14	export const OptionListItem: FC<Props> = ({
15	  item,
16	  activeItem,
17	  hasOpacity,
18	  imageHeight = 48,
19	  imageWidth = 56,
20	  setDirection,
21	}) => {
22	  const isActive = useMemo(
23	    () => activeItem.name === item.name,
24	    [activeItem, item.name],
25	  );
26	
27	  return (
28	    <button
29	      onClick={() => setDirection(item)}
30	      className={clsx(
31	        'w-[100px] md:w-[136px] px-12 py-20  md:p-20 flex flex-col gap-16 items-center rounded-lg border border-solid transition-all duration-300 ease-out',
32	        isActive
33	          ? 'border-global-primary-1 text-black font-medium'
34	          : 'border-transparent text-text-2 font-normal hover:border-border-5',
35	      )}
36	    >
37	      <Image
38	        className={clsx(!isActive && hasOpacity && 'opacity-50')}
39	        src={item.imgSrc || ''}
40	        alt={item.type}
41	        width={imageWidth}
42	        height={imageHeight}
43	      />
44	      <span className="capitalize">{item.name}</span>
45	    </button>
46	  );
47	};
